css:
.stratcraft-sim-container {
    padding: 28px;
    background: #f4f6fa;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: #1a2744;
}

.stratcraft-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2b3d63 100%);
    color: #f4f6fa;
    border-radius: 4px;
    padding: 28px 32px;
    margin-bottom: 24px;
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    flex-wrap: wrap;
    gap: 20px;
    border-left: 6px solid #c9a34a;
}
.stratcraft-sim-header-brand { flex: 1 1 60%; min-width: 280px; }
.stratcraft-sim-brand-tag {
    display: inline-block;
    font-size: 0.7rem;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: #c9a34a;
    margin-bottom: 8px;
    font-weight: 600;
}
.stratcraft-sim-header h1 {
    font-size: 1.55rem;
    font-weight: 600;
    margin: 0 0 6px 0;
    letter-spacing: 0.01em;
}
.stratcraft-sim-subtitle {
    margin: 0;
    color: #c6d1e5;
    font-size: 0.92rem;
    font-style: italic;
}
.stratcraft-sim-period-counter {
    background: rgba(201,163,74,0.12);
    border: 1px solid rgba(201,163,74,0.4);
    padding: 10px 18px;
    border-radius: 4px;
    font-size: 0.95rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #f4e7c6;
    font-weight: 500;
}
.stratcraft-sim-period-counter span { margin: 0 3px; }

.stratcraft-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.stratcraft-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d9e0ec;
    border-top: 3px solid #1a2744;
    border-radius: 4px;
    padding: 20px 22px;
    box-shadow: 0 1px 3px rgba(26,39,68,0.06);
}
.stratcraft-sim-kpi-approval { border-top-color: #1a2744; }
.stratcraft-sim-kpi-coherence { border-top-color: #2d7a63; }
.stratcraft-sim-kpi-resilience { border-top-color: #a8402a; }
.stratcraft-sim-kpi-archetype { border-top-color: #c9a34a; }
.stratcraft-sim-kpi-label {
    color: #6b7793;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
    font-weight: 600;
}
.stratcraft-sim-kpi-value {
    font-size: 2.3rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
    margin-bottom: 4px;
}
.stratcraft-sim-kpi-value-sm { font-size: 1.25rem; font-weight: 600; }
.stratcraft-sim-kpi-coherence .stratcraft-sim-kpi-value { color: #2d7a63; }
.stratcraft-sim-kpi-resilience .stratcraft-sim-kpi-value { color: #a8402a; }
.stratcraft-sim-kpi-archetype .stratcraft-sim-kpi-value { color: #8a6b1f; }
.stratcraft-sim-kpi-sub {
    color: #8996ae;
    font-size: 0.75rem;
    font-style: italic;
}

.stratcraft-sim-workspace {
    display: grid;
    grid-template-columns: 1.15fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
}
.stratcraft-sim-briefing {
    background: #ffffff;
    border: 1px solid #d9e0ec;
    border-left: 4px solid #1a2744;
    border-radius: 4px;
    padding: 24px 26px;
}
.stratcraft-sim-briefing-phase {
    font-size: 0.72rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #c9a34a;
    font-weight: 700;
    margin-bottom: 10px;
}
.stratcraft-sim-briefing h2 {
    font-size: 1.2rem;
    color: #1a2744;
    margin: 0 0 12px 0;
    font-weight: 600;
}
.stratcraft-sim-briefing p {
    color: #3d4b68;
    font-size: 0.95rem;
    line-height: 1.55;
    margin: 0;
}

.stratcraft-sim-controls {
    background: #ffffff;
    border: 1px solid #d9e0ec;
    border-radius: 4px;
    padding: 24px 26px;
}
.stratcraft-sim-controls h3 {
    font-size: 0.8rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #6b7793;
    font-weight: 700;
    margin: 0 0 18px 0;
    padding-bottom: 10px;
    border-bottom: 1px solid #e5e9f2;
}
.stratcraft-sim-decision-block, .stratcraft-sim-rationale-block {
    margin-bottom: 16px;
}
.stratcraft-sim-decision-block label, .stratcraft-sim-rationale-block label {
    display: block;
    font-size: 0.85rem;
    color: #1a2744;
    font-weight: 600;
    margin-bottom: 8px;
}

.stratcraft-sim-select {
    background: #ffffff;
    border: 1px solid #b9c3d6;
    color: #1a2744;
    border-radius: 3px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.92rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.stratcraft-sim-select:focus {
    outline: none;
    border-color: #1a2744;
    box-shadow: 0 0 0 3px rgba(26,39,68,0.12);
}
.stratcraft-sim-select option {
    background: #ffffff;
    color: #1a2744;
}

.stratcraft-sim-button-row {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-top: 8px;
}
.stratcraft-sim-primary-btn {
    background: #1a2744;
    color: #ffffff;
    border: 1px solid #1a2744;
    padding: 10px 22px;
    font-weight: 600;
    font-size: 0.9rem;
    letter-spacing: 0.04em;
    border-radius: 3px;
    transition: background 0.2s ease, transform 0.15s ease;
}
.stratcraft-sim-primary-btn:hover {
    background: #2b3d63;
    color: #ffffff;
    transform: translateY(-1px);
}
.stratcraft-sim-controls .btn-outline-secondary {
    border-color: #b9c3d6;
    color: #6b7793;
    background: #ffffff;
    font-size: 0.82rem;
    padding: 8px 16px;
}
.stratcraft-sim-controls .btn-outline-secondary:hover {
    background: #eef1f7;
    color: #1a2744;
    border-color: #6b7793;
}

.stratcraft-sim-history-zone, .stratcraft-sim-chart-zone {
    background: #ffffff;
    border: 1px solid #d9e0ec;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 20px;
}
.stratcraft-sim-history-zone h3, .stratcraft-sim-chart-zone h3 {
    font-size: 0.8rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #6b7793;
    font-weight: 700;
    margin: 0 0 14px 0;
}
.stratcraft-sim-history-zone table {
    font-size: 0.86rem;
    color: #1a2744;
    margin-bottom: 0;
}
.stratcraft-sim-history-zone table thead th {
    background: #eef1f7;
    color: #1a2744;
    font-weight: 600;
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border-bottom: 2px solid #c9a34a;
}
.stratcraft-sim-history-zone table td { vertical-align: middle; }

.stratcraft-sim-chart-zone canvas {
    max-height: 300px;
}

@media (max-width: 768px) {
    .stratcraft-sim-container { padding: 16px; }
    .stratcraft-sim-header {
        flex-direction: column;
        align-items: flex-start;
        padding: 20px;
    }
    .stratcraft-sim-header h1 { font-size: 1.2rem; }
    .stratcraft-sim-workspace { grid-template-columns: 1fr; }
    .stratcraft-sim-kpi-value { font-size: 1.8rem; }
}

