(function() {
    'use strict';

    class StratCraftAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'StratCraft Strategic Plan Builder';
            this.version = '1.0.0';

            // Ten-round script. Each round specifies the briefing text and the
            // option set. Options carry a primary archetype tag and a quality
            // score (0 to 10) used for scoring. War-game rounds are 7-9.
            this.ROUNDS = [
                { id: 'diagnosis', phaseKey: 'phase_analysis', titleKey: 'r1_title', descKey: 'r1_desc', labelKey: 'r1_label',
                  options: [
                      { v: 'A', tKey: 'r1_opt_A', arch: 'innovation', quality: 9 },
                      { v: 'B', tKey: 'r1_opt_B', arch: 'cost',       quality: 7 },
                      { v: 'C', tKey: 'r1_opt_C', arch: 'innovation', quality: 6 },
                      { v: 'D', tKey: 'r1_opt_D', arch: 'niche',      quality: 6 }
                  ]
                },
                { id: 'framework', phaseKey: 'phase_analysis', titleKey: 'r2_title', descKey: 'r2_desc', labelKey: 'r2_label',
                  options: [
                      { v: 'A', tKey: 'r2_opt_A', arch: 'innovation', quality: 8 },
                      { v: 'B', tKey: 'r2_opt_B', arch: 'blue_ocean', quality: 6 },
                      { v: 'C', tKey: 'r2_opt_C', arch: 'innovation', quality: 7 },
                      { v: 'D', tKey: 'r2_opt_D', arch: 'cost',       quality: 7 }
                  ]
                },
                { id: 'vision', phaseKey: 'phase_intent', titleKey: 'r3_title', descKey: 'r3_desc', labelKey: 'r3_label',
                  options: [
                      { v: 'A', tKey: 'r3_opt_A', arch: 'innovation', quality: 9 },
                      { v: 'B', tKey: 'r3_opt_B', arch: 'cost',       quality: 8 },
                      { v: 'C', tKey: 'r3_opt_C', arch: 'niche',      quality: 8 },
                      { v: 'D', tKey: 'r3_opt_D', arch: 'blue_ocean', quality: 7 }
                  ]
                },
                { id: 'pillar1', phaseKey: 'phase_intent', titleKey: 'r4_title', descKey: 'r4_desc', labelKey: 'r4_label',
                  options: [
                      { v: 'A', tKey: 'r4_opt_A', arch: 'innovation', quality: 9 },
                      { v: 'B', tKey: 'r4_opt_B', arch: 'cost',       quality: 7 },
                      { v: 'C', tKey: 'r4_opt_C', arch: 'blue_ocean', quality: 8 },
                      { v: 'D', tKey: 'r4_opt_D', arch: 'niche',      quality: 7 }
                  ]
                },
                { id: 'pillar2', phaseKey: 'phase_intent', titleKey: 'r5_title', descKey: 'r5_desc', labelKey: 'r5_label',
                  options: [
                      { v: 'A', tKey: 'r5_opt_A', arch: 'innovation', quality: 8 },
                      { v: 'B', tKey: 'r5_opt_B', arch: 'cost',       quality: 8 },
                      { v: 'C', tKey: 'r5_opt_C', arch: 'niche',      quality: 7 },
                      { v: 'D', tKey: 'r5_opt_D', arch: 'blue_ocean', quality: 8 }
                  ]
                },
                { id: 'allocation', phaseKey: 'phase_plan', titleKey: 'r6_title', descKey: 'r6_desc', labelKey: 'r6_label',
                  options: [
                      { v: 'A', tKey: 'r6_opt_A', arch: 'innovation', quality: 7 },
                      { v: 'B', tKey: 'r6_opt_B', arch: 'cost',       quality: 5 },
                      { v: 'C', tKey: 'r6_opt_C', arch: 'niche',      quality: 8 },
                      { v: 'D', tKey: 'r6_opt_D', arch: 'blue_ocean', quality: 7 }
                  ]
                },
                { id: 'wg_incumbent', phaseKey: 'phase_wargame', titleKey: 'r7_title', descKey: 'r7_desc', labelKey: 'r7_label',
                  options: [
                      { v: 'A', tKey: 'r7_opt_A', arch: 'innovation', quality: 8 },
                      { v: 'B', tKey: 'r7_opt_B', arch: 'cost',       quality: 6 },
                      { v: 'C', tKey: 'r7_opt_C', arch: 'niche',      quality: 7 },
                      { v: 'D', tKey: 'r7_opt_D', arch: 'blue_ocean', quality: 7 }
                  ]
                },
                { id: 'wg_disruptor', phaseKey: 'phase_wargame', titleKey: 'r8_title', descKey: 'r8_desc', labelKey: 'r8_label',
                  options: [
                      { v: 'A', tKey: 'r8_opt_A', arch: 'innovation', quality: 9 },
                      { v: 'B', tKey: 'r8_opt_B', arch: 'cost',       quality: 6 },
                      { v: 'C', tKey: 'r8_opt_C', arch: 'blue_ocean', quality: 7 },
                      { v: 'D', tKey: 'r8_opt_D', arch: 'niche',      quality: 6 }
                  ]
                },
                { id: 'wg_activist', phaseKey: 'phase_wargame', titleKey: 'r9_title', descKey: 'r9_desc', labelKey: 'r9_label',
                  options: [
                      { v: 'A', tKey: 'r9_opt_A', arch: 'innovation', quality: 8 },
                      { v: 'B', tKey: 'r9_opt_B', arch: 'niche',      quality: 5 },
                      { v: 'C', tKey: 'r9_opt_C', arch: 'blue_ocean', quality: 8 },
                      { v: 'D', tKey: 'r9_opt_D', arch: 'cost',       quality: 6 }
                  ]
                },
                { id: 'revision', phaseKey: 'phase_revise', titleKey: 'r10_title', descKey: 'r10_desc', labelKey: 'r10_label',
                  options: [
                      { v: 'A', tKey: 'r10_opt_A', arch: 'innovation', quality: 9 },
                      { v: 'B', tKey: 'r10_opt_B', arch: 'niche',      quality: 8 },
                      { v: 'C', tKey: 'r10_opt_C', arch: 'cost',       quality: 7 },
                      { v: 'D', tKey: 'r10_opt_D', arch: 'blue_ocean', quality: 7 }
                  ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    boardApproval: 50,
                    strategicCoherence: 0,
                    resilience: 0,
                    archetypeTally: { innovation: 0, cost: 0, niche: 0, blue_ocean: 0 },
                    dominantArchetype: 'undefined',
                    approvalHistory: [],
                    coherenceHistory: [],
                    resilienceHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { choice: 'A', confidence: 'mid' };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const sel = document.getElementById('decisionSelect');
            const conf = document.getElementById('rationaleSelect');
            if (sel) decisions.choice = sel.value;
            if (conf) decisions.confidence = conf.value;

            const state = window.mySimulation.state;
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const valid = round.options.some((o) => o.v === decisions.choice);
            if (!valid) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }
            decisions.roundId = round.id;
            return true;
        }

        calculateResults(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const opt = round.options.find((o) => o.v === state.decisions.choice) || round.options[0];

            const ds = state.domainState;
            ds.archetypeTally[opt.arch] = (ds.archetypeTally[opt.arch] || 0) + 1;

            const tally = ds.archetypeTally;
            const keys = Object.keys(tally);
            let total = 0;
            let topKey = keys[0];
            keys.forEach((k) => {
                total += tally[k];
                if (tally[k] > tally[topKey]) topKey = k;
            });
            const coherence = total > 0 ? Math.round((tally[topKey] / total) * 100) : 0;
            ds.strategicCoherence = coherence;
            ds.dominantArchetype = topKey;

            const confMult = state.decisions.confidence === 'high' ? 1.15
                            : state.decisions.confidence === 'low' ? 0.85 : 1.0;
            const alignBonus = (opt.arch === topKey) ? 3 : -2;
            const deltaBA = Math.round(((opt.quality + alignBonus) * confMult) - 4);
            ds.boardApproval = Math.max(0, Math.min(100, ds.boardApproval + deltaBA));

            let deltaRes = 0;
            const isWarGame = (state.currentPeriod >= 7 && state.currentPeriod <= 9);
            if (isWarGame) {
                const baseRes = opt.quality;
                const alignResBonus = (opt.arch === topKey) ? 6 : 0;
                deltaRes = Math.round((baseRes + alignResBonus) * confMult);
                ds.resilience = Math.max(0, Math.min(100, ds.resilience + deltaRes));
            }

            ds.approvalHistory.push(ds.boardApproval);
            ds.coherenceHistory.push(coherence);
            ds.resilienceHistory.push(ds.resilience);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 400);

            return {
                period: state.currentPeriod,
                round: round.id,
                choice: opt.v,
                archetype: opt.arch,
                quality: opt.quality,
                confidence: state.decisions.confidence,
                deltaApproval: deltaBA,
                deltaResilience: deltaRes,
                boardApproval: ds.boardApproval,
                coherence: coherence,
                resilience: ds.resilience,
                dominant: topKey
            };
        }

        _archetypeLabel(key) {
            const map = {
                innovation: window.mySimulation ? window.mySimulation.t('arch_innovation') : 'Innovation Leader',
                cost:       window.mySimulation ? window.mySimulation.t('arch_cost')       : 'Cost Leader',
                niche:      window.mySimulation ? window.mySimulation.t('arch_niche')      : 'Niche Focus',
                blue_ocean: window.mySimulation ? window.mySimulation.t('arch_blue')       : 'Blue Ocean',
                undefined:  window.mySimulation ? window.mySimulation.t('archetype_undef') : 'Undefined'
            };
            return map[key] || key;
        }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const phaseEl = document.getElementById('briefingPhase');
            if (phaseEl) phaseEl.textContent = t(round.phaseKey);

            const titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);

            const descEl = document.getElementById('briefingText');
            if (descEl) descEl.innerHTML = t(round.descKey);

            const labelEl = document.getElementById('decisionLabel');
            if (labelEl) labelEl.textContent = t(round.labelKey);

            const sel = document.getElementById('decisionSelect');
            if (sel) {
                const prev = sel.value;
                sel.innerHTML = '';
                round.options.forEach((opt) => {
                    const o = document.createElement('option');
                    o.value = opt.v;
                    o.textContent = t(opt.tKey);
                    sel.appendChild(o);
                });
                const stillValid = round.options.some((o) => o.v === prev);
                sel.value = stillValid ? prev : round.options[0].v;
            }

            const archEl = document.getElementById('archetypeDisplay');
            if (archEl && state.domainState) {
                archEl.textContent = this._archetypeLabel(state.domainState.dominantArchetype || 'undefined');
            }
            const cohEl = document.getElementById('coherenceDisplay');
            if (cohEl && state.domainState) {
                const c = state.domainState.strategicCoherence || 0;
                cohEl.textContent = c > 0 ? (c + '%') : '—';
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('approvalDisplay', 'domainState.boardApproval',
                (v) => Math.round(v));
            uiManager.bind('resilienceDisplay', 'domainState.resilience',
                (v) => Math.round(v));
        }

        getChartConfig() {
            return {
                trajectoryChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Board Approval',
                                data: [],
                                borderColor: '#1a2744',
                                backgroundColor: 'rgba(26,39,68,0.10)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25
                            },
                            {
                                label: 'Strategic Coherence',
                                data: [],
                                borderColor: '#2d7a63',
                                backgroundColor: 'rgba(45,122,99,0.08)',
                                borderWidth: 2,
                                borderDash: [6, 4],
                                fill: false,
                                tension: 0.25
                            },
                            {
                                label: 'War-Game Resilience',
                                data: [],
                                borderColor: '#a8402a',
                                backgroundColor: 'rgba(168,64,42,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Strategic Plan Trajectory' },
                            legend: { position: 'bottom' }
                        },
                        scales: {
                            y: { beginAtZero: true, suggestedMax: 100 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const labels = state.domainState.approvalHistory.map((_, i) => 'R' + (i + 1));
            return {
                trajectoryChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.approvalHistory },
                        { data: state.domainState.coherenceHistory },
                        { data: state.domainState.resilienceHistory }
                    ]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.deltaApproval < 0) return window.mySimulation.t('hint_loss');
            if (results.coherence < 40 && state.currentPeriod >= 4) return window.mySimulation.t('hint_incoherent');
            if (state.currentPeriod >= 7 && state.currentPeriod <= 9 && results.deltaResilience < 8) return window.mySimulation.t('hint_weak_defense');
            if (results.coherence >= 70) return window.mySimulation.t('hint_coherent');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.round',        label: 'Round',         i18nKey: 'col_round' },
                { key: 'results.choice',       label: 'Choice',        i18nKey: 'col_choice' },
                { key: 'results.archetype',    label: 'Archetype',     i18nKey: 'col_archetype' },
                { key: 'results.confidence',   label: 'Confidence',    i18nKey: 'col_confidence' },
                { key: 'results.deltaApproval', label: 'Board Delta',  i18nKey: 'col_delta_ba',
                  formatter: (v) => (v >= 0 ? '+' : '') + v },
                { key: 'results.boardApproval', label: 'Board Approval', i18nKey: 'col_board',
                  formatter: (v) => v + '/100' },
                { key: 'results.coherence',    label: 'Coherence',      i18nKey: 'col_coherence',
                  formatter: (v) => v + '%' },
                { key: 'results.resilience',   label: 'Resilience',     i18nKey: 'col_resilience' }
            ];
        }

        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const last = history[history.length - 1].results || {};
            const finalBA = last.boardApproval || 0;
            const finalCoh = last.coherence || 0;
            const finalRes = last.resilience || 0;

            const composite = Math.round((finalBA * 0.45) + (finalCoh * 0.30) + (finalRes * 0.25));

            let performance = 'Beginner';
